vertex:
#version 300 es

struct VS_OUT
{
    vec3 vTint;
    float vAlpha;
};

layout(std140) uniform ObjectUniformBuffer
{
    mat4 g_mModel;
    mat4 g_mView;
    mat4 g_mProj;
    vec3 g_vLightPos;
    vec3 g_vLightColor;
    vec3 g_vCameraPos;
    float g_flTime;
} g_oUbo;

out vec3 vdspv_fsin0_vTint;
out float vdspv_fsin0_vAlpha;
layout(location = 1) in vec3 tint;
layout(location = 2) in vec2 texCoords;
layout(location = 0) in vec3 position;

void main()
{
    vdspv_fsin0_vTint = tint;
    vdspv_fsin0_vAlpha = texCoords.x;
    gl_Position = (g_oUbo.g_mProj * g_oUbo.g_mView) * vec4(position, 1.0);
    gl_Position.z = 2.0 * gl_Position.z - gl_Position.w;
    gl_Position.y = -gl_Position.y;
}

fragment:
#version 300 es
precision mediump float;
precision highp int;

struct VS_OUT
{
    highp vec3 vTint;
    highp float vAlpha;
};

layout(location = 0) out highp vec4 fragColor;
in highp vec3 vdspv_fsin0_vTint;
in highp float vdspv_fsin0_vAlpha;

void main()
{
    fragColor = vec4(vdspv_fsin0_vTint, vdspv_fsin0_vAlpha);
}
